import { useState, useEffect } from 'react';
import API from '../../api/axios';
import toast from 'react-hot-toast';
import { useNavigate } from 'react-router-dom';

export default function AdminCardRegister() {
  const [customers, setCustomers] = useState([]);
  const [selectedCustomerId, setSelectedCustomerId] = useState('');
  const [cardUid, setCardUid] = useState('');
  const [loading, setLoading] = useState(false);
  
  const adminInfo = JSON.parse(localStorage.getItem('userInfo')) || {};
  const navigate = useNavigate();

  useEffect(() => {
    const fetchCustomers = async () => {
      if (!adminInfo.companyId?._id && !adminInfo.companyId) return;
      const compId = adminInfo.companyId._id || adminInfo.companyId;

      try {
        const { data } = await API.get(`/users/company/${compId}`);
        setCustomers(data);
      } catch (error) {
        toast.error('Failed to load customers');
      }
    };
    fetchCustomers();
  }, []);

  const handleRegisterCard = async (e) => {
    e.preventDefault();
    setLoading(true);

    try {
      const { data } = await API.post('/cards/register', {
        uid: cardUid.trim(),
        userId: selectedCustomerId
      });

      toast.success(data.message);
      setCardUid('');
      setSelectedCustomerId('');
    } catch (error) {
      toast.error(error.response?.data?.message || 'Card registration failed');
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = async () => {
    await API.post('/auth/logout');
    localStorage.removeItem('userInfo');
    navigate('/');
  };

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-xl mx-auto space-y-6">
        
        {/* Header */}
        <div className="flex justify-between items-center bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          <div>
            <h1 className="text-xl font-bold text-gray-900">Link RFID Card</h1>
            <p className="text-sm text-gray-500">Admin Portal • {adminInfo.fullName}</p>
          </div>
          <button 
            onClick={handleLogout}
            className="px-4 py-2 bg-red-50 hover:bg-red-100 text-red-600 font-medium rounded-lg text-sm transition"
          >
            Sign Out
          </button>
        </div>

        {/* Card Registration Form */}
        <div className="bg-white p-6 rounded-2xl shadow-sm border border-gray-100">
          <form onSubmit={handleRegisterCard} className="space-y-4">
            <div>
              <label className="block text-xs font-semibold uppercase tracking-wider text-gray-600 mb-1">Select Customer</label>
              <select
                value={selectedCustomerId}
                onChange={(e) => setSelectedCustomerId(e.target.value)}
                required
                className="w-full px-4 py-2.5 bg-gray-50 border border-gray-300 rounded-lg text-gray-800 focus:outline-none focus:ring-2 focus:ring-gray-900 text-sm"
              >
                <option value="" disabled>-- Choose a Customer --</option>
                {customers.map((c) => (
                  <option key={c._id} value={c._id}>
                    {c.fullName} ({c.email})
                  </option>
                ))}
              </select>
            </div>

            <div>
              <label className="block text-xs font-semibold uppercase tracking-wider text-gray-600 mb-1">RFID Card UID</label>
              <input
                type="text"
                value={cardUid}
                onChange={(e) => setCardUid(e.target.value)}
                placeholder="e.g. A3 B4 C5 D6"
                required
                className="w-full px-4 py-2.5 bg-gray-50 border border-gray-300 rounded-lg text-gray-800 focus:outline-none focus:ring-2 focus:ring-gray-900 text-sm uppercase"
              />
              <p className="text-xs text-gray-400 mt-1">Scan the RFID tag on your hardware reader to capture the unique identifier string.</p>
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full py-3 bg-gray-900 hover:bg-gray-800 text-white font-medium rounded-lg text-sm transition shadow-sm disabled:opacity-50"
            >
              {loading ? 'Linking Card...' : 'Save & Link Card'}
            </button>
          </form>
        </div>

      </div>
    </div>
  );
}
